WITH recent_web_events AS (SELECT * FROM web_events WHERE page = '/checkout' AND duration_sec BETWEEN 199 AND 222), EventQuarterSummary AS (SELECT QUARTER(event_time) AS event_quarter, MAX(duration_sec) - MIN(duration_sec) AS duration_sec_range, AVG(duration_sec) AS avg_duration_sec FROM recent_web_events GROUP BY QUARTER(event_time)) SELECT event_quarter, duration_sec_range, avg_duration_sec FROM EventQuarterSummary WHERE duration_sec_range < 51;
